#include <list>
#include <iostream>
#include <utility>

void print_swap_status(const std::list<int>& l, const std::string& name) {
    std::cout << name << " size: " << l.size() << ", front: " 
              << (l.empty() ? "(empty)" : std::to_string(l.front())) << "\n";
}

int main() {
    std::list<int> l1 = {1, 2, 3, 4000000}; // Large list
    std::list<int> l2 = {99, 100};

    // O(1) operation, regardless of size
    l1.swap(l2);

    print_swap_status(l1, "L1"); // L1 now has {99, 100}
    print_swap_status(l2, "L2"); // L2 now has {1, 2, 3, 4000000}
}
